import { writable } from 'svelte/store';

export const count = writable(0);

// ❌ OLD: Outside a component there is no $ sugar. You must call
// subscribe and keep the returned unsubscribe function, and call it
// when done — forgetting it leaks the subscriber (and its closure)
// forever.
const unsub = count.subscribe((v) => {
  console.log('count is', v); // ❌ OLD: manual callback
});

// later...
unsub(); // ❌ OLD: manual teardown — easy to forget

// A subscription that is never unsubscribed keeps the callback alive
// and can accumulate in long-lived modules.
